CREATE DATABASE IF NOT EXISTS sanitas_ev02 CHARACTER SET utf8mb4; USE sanitas_ev02;
CREATE TABLE IF NOT EXISTS paciente(id INT PRIMARY KEY AUTO_INCREMENT,nombre VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS medico(id INT PRIMARY KEY AUTO_INCREMENT,nombre VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS cita(id INT PRIMARY KEY AUTO_INCREMENT,paciente_id INT NOT NULL,medico_id INT NOT NULL,fecha DATETIME NOT NULL,estado ENUM('PENDIENTE','ATENDIDA','CANCELADA') DEFAULT 'PENDIENTE', turno DATETIME GENERATED ALWAYS AS (CASE WHEN estado='CANCELADA' THEN NULL ELSE fecha END) STORED, UNIQUE(medico_id,turno), FOREIGN KEY(paciente_id) REFERENCES paciente(id),FOREIGN KEY(medico_id) REFERENCES medico(id));
INSERT IGNORE INTO paciente(id,nombre) VALUES(1,'Paciente de prueba A'),(2,'Paciente de prueba B');
INSERT IGNORE INTO medico(id,nombre) VALUES(1,'Profesional de prueba A'),(2,'Profesional de prueba B');